/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Can_Irq_Func can_set_irq_func (Can_Irq_Func irq_func)
{
  CRITICAL ;

  Can_Irq_Func irq_func_old ;

  C_ENTER ;
    {
      irq_func_old = can_irq_func ;
      can_irq_func = irq_func     ;
    }
  C_LEAVE ;

  return irq_func_old ;
}


